// Copies the embedded recording mock WebGL 2 context (src/renderers/webgl/webgl_mock_gl_test.mbt,
// generated by diff/core/webgl/tools/gen_mock.mjs) into
// src/renderers/webgl_fallback/g10_mock_gl_test.mbt, under its own extern name.
//
//   node tools/gen_g10_mock.mjs [--check]   (--check: write nothing, exit 1 if stale)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repo = path.resolve( path.dirname( fileURLToPath( import.meta.url ) ), '..' );
const out = path.join( repo, 'src/renderers/webgl_fallback/g10_mock_gl_test.mbt' );
let s = fs.readFileSync( path.join( repo, 'src/renderers/webgl/webgl_mock_gl_test.mbt' ), 'utf8' );
const head = /^\/\/ Generated by [^\n]*\n\/\/[^\n]*\n/;
if ( ! head.test( s ) ) throw new Error( 'unexpected header in webgl_mock_gl_test.mbt' );
s = s.replace( head, '// Copied by tools/gen_g10_mock.mjs from src/renderers/webgl/webgl_mock_gl_test.mbt\n// (generated by diff/core/webgl/tools/gen_mock.mjs): the recording mock WebGL 2 context.\n' );
s = s.replace( 'fn ffi_mock_gl_module(', 'fn g10_ffi_mock_gl_module(' );
if ( process.argv.includes( '--check' ) ) {

	const ok = fs.existsSync( out ) && fs.readFileSync( out, 'utf8' ) === s;
	console.log( ok ? 'src/renderers/webgl_fallback/g10_mock_gl_test.mbt is up to date' : 'src/renderers/webgl_fallback/g10_mock_gl_test.mbt is stale (run node tools/gen_g10_mock.mjs)' );
	process.exit( ok ? 0 : 1 );

}

fs.writeFileSync( out, s );
console.log( 'wrote', path.relative( repo, out ) );
